using System;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using PricingEngine;

namespace PricingEngine.Tests;

[TestClass]
public sealed class DiscountCalculatorTests
{
    private readonly DiscountCalculator _calc = new();

    // -- CalculateDiscount tests --

    [TestMethod]
    public void CalculateDiscount_LargeOrder_Returns15Percent()
    {
        Assert.AreEqual(300m, _calc.CalculateDiscount(2000m));
    }

    [TestMethod]
    public void CalculateDiscount_Exactly1000_Returns15Percent()
    {
        Assert.AreEqual(150m, _calc.CalculateDiscount(1000m));
    }

    [TestMethod]
    public void CalculateDiscount_JustBelow1000_Returns10Percent()
    {
        Assert.AreEqual(99.9m, _calc.CalculateDiscount(999m));
    }

    [TestMethod]
    public void CalculateDiscount_MediumOrder_Returns10Percent()
    {
        Assert.AreEqual(75m, _calc.CalculateDiscount(750m));
    }

    [TestMethod]
    public void CalculateDiscount_Exactly500_Returns10Percent()
    {
        Assert.AreEqual(50m, _calc.CalculateDiscount(500m));
    }

    [TestMethod]
    public void CalculateDiscount_JustBelow500_Returns5Percent()
    {
        Assert.AreEqual(24.95m, _calc.CalculateDiscount(499m));
    }

    [TestMethod]
    public void CalculateDiscount_SmallOrder_Returns5Percent()
    {
        Assert.AreEqual(10m, _calc.CalculateDiscount(200m));
    }

    [TestMethod]
    public void CalculateDiscount_Exactly100_Returns5Percent()
    {
        Assert.AreEqual(5m, _calc.CalculateDiscount(100m));
    }

    [TestMethod]
    public void CalculateDiscount_JustBelow100_ReturnsZero()
    {
        Assert.AreEqual(0m, _calc.CalculateDiscount(99m));
    }

    [TestMethod]
    public void CalculateDiscount_TinyOrder_ReturnsZero()
    {
        Assert.AreEqual(0m, _calc.CalculateDiscount(50m));
    }

    [TestMethod]
    public void CalculateDiscount_Zero_ReturnsZero()
    {
        Assert.AreEqual(0m, _calc.CalculateDiscount(0m));
    }

    [TestMethod]
    public void CalculateDiscount_NegativeAmount_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calc.CalculateDiscount(-1m));
    }

    // -- CalculateShipping tests --

    [TestMethod]
    public void CalculateShipping_LargeOrder_FreeShipping()
    {
        Assert.AreEqual(0m, _calc.CalculateShipping(500m, 2.0, false));
    }

    [TestMethod]
    public void CalculateShipping_JustAbove250_FreeShipping()
    {
        Assert.AreEqual(0m, _calc.CalculateShipping(250.01m, 2.0, false));
    }

    [TestMethod]
    public void CalculateShipping_Exactly250_NotFree()
    {
        // 250 is NOT > 250, so shipping is charged
        Assert.AreEqual(6.00m, _calc.CalculateShipping(250m, 2.0, false));
    }

    [TestMethod]
    public void CalculateShipping_SmallOrder_ReturnsBaseCost()
    {
        // baseCost = 5.00 + (2.0 * 0.50) = 6.00
        Assert.AreEqual(6.00m, _calc.CalculateShipping(50m, 2.0, false));
    }

    [TestMethod]
    public void CalculateShipping_HeavyItem_AddsHeavyFee()
    {
        // baseCost = 5.00 + (11.0 * 0.50) = 10.50, +15.00 heavy fee = 25.50
        Assert.AreEqual(25.50m, _calc.CalculateShipping(50m, 11.0, false));
    }

    [TestMethod]
    public void CalculateShipping_Exactly10Kg_NoHeavyFee()
    {
        // 10.0 is NOT > 10.0, so no heavy item fee
        // baseCost = 5.00 + (10.0 * 0.50) = 10.00
        Assert.AreEqual(10.00m, _calc.CalculateShipping(50m, 10.0, false));
    }

    [TestMethod]
    public void CalculateShipping_Express_Adds50PercentSurcharge()
    {
        // baseCost = 5.00 + (2.0 * 0.50) = 6.00, * 1.50 = 9.00
        Assert.AreEqual(9.00m, _calc.CalculateShipping(50m, 2.0, true));
    }

    [TestMethod]
    public void CalculateShipping_ExpressHeavy_AppliesBothFees()
    {
        // baseCost = 5.00 + (11.0 * 0.50) = 10.50, +15.00 = 25.50, * 1.50 = 38.25
        Assert.AreEqual(38.25m, _calc.CalculateShipping(50m, 11.0, true));
    }

    [TestMethod]
    public void CalculateShipping_ZeroWeight_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calc.CalculateShipping(50m, 0, false));
    }

    [TestMethod]
    public void CalculateShipping_ZeroOrderTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calc.CalculateShipping(0m, 2.0, false));
    }

    // -- ApplyCoupon tests --

    [TestMethod]
    public void ApplyCoupon_Save10_Applies10Percent()
    {
        Assert.AreEqual(90m, _calc.ApplyCoupon(100m, "SAVE10"));
    }

    [TestMethod]
    public void ApplyCoupon_Save20_Applies20Percent()
    {
        Assert.AreEqual(80m, _calc.ApplyCoupon(100m, "SAVE20"));
    }

    [TestMethod]
    public void ApplyCoupon_Flat5_SubtractsFive()
    {
        Assert.AreEqual(95m, _calc.ApplyCoupon(100m, "FLAT5"));
    }

    [TestMethod]
    public void ApplyCoupon_Flat50_SubtractsFifty()
    {
        Assert.AreEqual(150m, _calc.ApplyCoupon(200m, "FLAT50"));
    }

    [TestMethod]
    public void ApplyCoupon_UnknownCode_ReturnsOriginalTotal()
    {
        Assert.AreEqual(100m, _calc.ApplyCoupon(100m, "BOGUS"));
    }

    [TestMethod]
    public void ApplyCoupon_CaseInsensitive()
    {
        Assert.AreEqual(90m, _calc.ApplyCoupon(100m, "save10"));
    }

    [TestMethod]
    public void ApplyCoupon_FloorAt1Dollar_WhenDiscountExceedsTotal()
    {
        // FLAT50 on a $2 order: 2 - 50 = -48, clamped to 1.00
        Assert.AreEqual(1.00m, _calc.ApplyCoupon(2m, "FLAT50"));
    }

    [TestMethod]
    public void ApplyCoupon_FloorAt1Dollar_WhenResultExactly1()
    {
        // Ensure result == 1.00 is returned as-is (not clamped further)
        // FLAT5 on $6: 6 - 5 = 1.00
        Assert.AreEqual(1.00m, _calc.ApplyCoupon(6m, "FLAT5"));
    }

    [TestMethod]
    public void ApplyCoupon_NullCoupon_Throws()
    {
        Assert.ThrowsExactly<ArgumentNullException>(
            () => _calc.ApplyCoupon(100m, null!));
    }

    [TestMethod]
    public void ApplyCoupon_ZeroTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calc.ApplyCoupon(0m, "SAVE10"));
    }
}

